//! SHARED PRIVATE physical Root registration reader. DATA, never Source grant.
//! Actual original Root/credential/current/holder AND remains with each owner.
#![allow(unsafe_code)]
use std::{fs::{self,File,OpenOptions,Metadata},os::{fd::AsRawFd,unix::fs::{MetadataExt,OpenOptionsExt,FileExt}},path::{Path,Component},mem::ManuallyDrop,marker::PhantomData,rc::Rc,thread::{self,ThreadId}};
use serde::{Serialize,Deserialize};use sha2::{Digest,Sha256};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub(crate)enum Error{Required,Shape,Changed,Thread,Unknown}
#[derive(Clone,Copy)]pub(crate)struct Identity{pub device:u64,pub inode:u64,pub uid:u32,pub gid:u32,pub mode:u32}
pub(crate)struct QualificationExpected<'a>{pub parent:&'a Path,pub identity:Identity,pub resource_id:&'a str,pub bootstrap:&'a str,pub statement_family:u32,pub role:u32,pub process_uid:u32,pub process_gid:u32,pub scope_sha256:[u8;32],pub credential_sha256:[u8;32],pub actual_image:&'a Path,pub actual_image_sha256:[u8;32]}
#[derive(Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub(crate)struct QualificationDATA{pub(crate) version:u32,pub(crate) kind:String,pub(crate) resource_id:String,pub(crate) bootstrap:String,pub(crate) profile:u32,pub(crate) statement_family:u32,pub(crate) role:u32,pub(crate) process_uid:u32,pub(crate) process_gid:u32,pub(crate) scope_sha256:[u8;32],pub(crate) credential_sha256:[u8;32],pub(crate) source_epoch:u64,pub(crate) resource_generation:u64,pub(crate) native_image_path:String,pub(crate) native_image_sha256:[u8;32]}
struct HeldFD{file:ManuallyDrop<File>,path:String,identity:Metadata,is_directory:bool,close_selected:bool,closed:bool}
pub(crate)struct HeldQualification{fds:Vec<HeldFD>,original:Vec<u8>,sha:[u8;32],epoch:u64,thread:ThreadId,first:Option<Error>,close_selected:bool,closed:bool,local:PhantomData<Rc<()>>}
pub(crate)struct Acquisition{pub owner:Option<HeldQualification>,pub error:Option<Error>}
fn same(a:&Metadata,b:&Metadata)->bool{a.dev()==b.dev()&&a.ino()==b.ino()&&a.uid()==b.uid()&&a.gid()==b.gid()&&a.mode()==b.mode()&&a.nlink()==b.nlink()&&a.len()==b.len()&&a.mtime()==b.mtime()&&a.mtime_nsec()==b.mtime_nsec()&&a.ctime()==b.ctime()&&a.ctime_nsec()==b.ctime_nsec()}
fn directory_same(a:&Metadata,b:&Metadata)->bool{a.is_dir()&&b.is_dir()&&!b.file_type().is_symlink()&&a.dev()==b.dev()&&a.ino()==b.ino()&&a.uid()==b.uid()&&a.gid()==b.gid()&&a.mode()==b.mode()}
fn digest(b:&[u8])->[u8;32]{Sha256::digest(b).into()}
#[cfg(target_os="linux")]fn directory_flags()->i32{libc::O_PATH|libc::O_NOFOLLOW|libc::O_CLOEXEC|libc::O_DIRECTORY}
#[cfg(not(target_os="linux"))]fn directory_flags()->i32{libc::O_NOFOLLOW|libc::O_CLOEXEC|libc::O_NONBLOCK|libc::O_DIRECTORY}
fn read(file:&File,n:usize)->Result<Vec<u8>,Error>{let mut b=vec![0;n.checked_add(1).ok_or(Error::Shape)?];let mut at=0;while at<b.len(){let size=file.read_at(&mut b[at..],at as u64).map_err(|_|Error::Changed)?;if size==0{break}at+=size;}if at!=n{return Err(Error::Changed)}b.truncate(n);Ok(b)}
impl HeldQualification{
 #[cfg(test)]pub(super)fn open_public(e:&QualificationExpected<'_>,root_uid:u32)->Acquisition{Self::open_exact(e,root_uid)}
 pub(crate)fn open(e:&QualificationExpected<'_>)->Acquisition{Self::open_exact(e,0)}
 fn open_exact(e:&QualificationExpected<'_>,root_uid:u32)->Acquisition{
  let mut owner=Self{fds:Vec::new(),original:Vec::new(),sha:[0;32],epoch:0,thread:thread::current().id(),first:None,close_selected:false,closed:false,local:PhantomData};
  let result=(||{if !e.parent.is_absolute()||!e.parent.components().all(|v|matches!(v,Component::RootDir|Component::Normal(_)))||e.resource_id.is_empty()||e.resource_id.len()>128||e.bootstrap.is_empty()||e.bootstrap.len()>128||e.statement_family!=5||!(1..=2).contains(&e.role)||e.scope_sha256==[0;32]||e.credential_sha256==[0;32]||e.actual_image_sha256==[0;32]||!e.actual_image.is_absolute()||fs::canonicalize(e.parent).map_err(|_|Error::Changed)?!=e.parent{return Err(Error::Shape)}
   // Open each exact Root-controlled ancestor deliberately, no mkdir/path IO.
   let mut paths:Vec<_>=e.parent.ancestors().collect();paths.reverse();for path in paths{let identity=fs::symlink_metadata(path).map_err(|_|Error::Changed)?;if !identity.is_dir()||identity.file_type().is_symlink()||identity.uid()!=0&&identity.uid()!=root_uid||identity.mode()&0o022!=0{return Err(Error::Changed)}if path==e.parent{let i=e.identity;if identity.dev()!=i.device||identity.ino()!=i.inode||identity.uid()!=i.uid||identity.gid()!=i.gid||identity.mode()&0o7777!=i.mode||i.uid!=root_uid||i.mode&0o022!=0{return Err(Error::Changed)}}let file=OpenOptions::new().read(true).custom_flags(directory_flags()).open(path).map_err(|_|Error::Changed)?;owner.fds.push(HeldFD{file:ManuallyDrop::new(file),path:path.to_str().ok_or(Error::Shape)?.into(),identity,is_directory:true,close_selected:false,closed:false});}
   let path=e.parent.join("source-role-qualification.public.json");let identity=fs::symlink_metadata(&path).map_err(|_|Error::Changed)?;let file=OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW|libc::O_CLOEXEC|libc::O_NONBLOCK).open(&path).map_err(|_|Error::Changed)?;owner.fds.push(HeldFD{file:ManuallyDrop::new(file),path:path.to_str().ok_or(Error::Shape)?.into(),identity,is_directory:false,close_selected:false,closed:false});let fd=owner.fds.last().unwrap();let s=&fd.identity;if !s.is_file()||s.file_type().is_symlink()||s.uid()!=root_uid||s.gid()!=e.identity.gid||s.nlink()!=1||![0o400,0o440,0o444,0o600,0o640].contains(&(s.mode()&0o7777))||s.len()==0||s.len()>32768{return Err(Error::Changed)}owner.original=read(&fd.file,s.len()as usize)?;owner.sha=digest(&owner.original);let v:QualificationDATA=serde_json::from_slice(&owner.original).map_err(|_|Error::Shape)?;if serde_json::to_vec(&v).map_err(|_|Error::Shape)?!=owner.original||v.version!=1||v.kind!="SOCIAL_SOURCE9_ORDINARY_RESOURCE_V1"||v.resource_id!=e.resource_id||v.bootstrap!=e.bootstrap||v.profile!=1||v.statement_family!=e.statement_family||v.role!=e.role||v.process_uid!=e.process_uid||v.process_gid!=e.process_gid||v.scope_sha256!=e.scope_sha256||v.credential_sha256!=e.credential_sha256||v.source_epoch==0||v.resource_generation==0||Path::new(&v.native_image_path)!=e.actual_image||v.native_image_sha256!=e.actual_image_sha256{return Err(Error::Required)}owner.epoch=v.source_epoch;owner.current()
  })();let error=result.err();if let Some(e)=error{owner.first=Some(e)}if owner.fds.is_empty(){owner.closed=true;Acquisition{owner:None,error}}else{Acquisition{owner:Some(owner),error}}
 }
 pub(crate)fn current(&mut self)->Result<(),Error>{if self.thread!=thread::current().id(){return Err(Error::Thread)}if let Some(e)=self.first{return Err(e)}if self.close_selected||self.closed{return Err(Error::Unknown)}let result=(||{for fd in &self.fds{let open=fd.file.metadata().map_err(|_|Error::Changed)?;let named=fs::symlink_metadata(&fd.path).map_err(|_|Error::Changed)?;let match_fd=if fd.is_directory{directory_same(&fd.identity,&open)&&directory_same(&fd.identity,&named)}else{same(&fd.identity,&open)&&same(&fd.identity,&named)};if !match_fd{return Err(Error::Changed)}if !fd.is_directory{let b=read(&fd.file,self.original.len())?;if b!=self.original||digest(&b)!=self.sha||!same(&open,&fd.file.metadata().map_err(|_|Error::Changed)?){return Err(Error::Changed)}}}Ok(())})();if let Err(e)=result{self.first=Some(e)}result}
 pub(crate)fn source_epoch_data(&mut self)->Result<u64,Error>{self.current()?;Ok(self.epoch)}
 pub(crate)fn close(&mut self)->Result<(),Error>{if self.thread!=thread::current().id(){return Err(Error::Thread)}if self.close_selected{return if self.closed{Ok(())}else{Err(Error::Unknown)}}self.close_selected=true;for fd in self.fds.iter_mut().rev(){if fd.close_selected&&!fd.closed{return Err(Error::Unknown)}fd.close_selected=true;if unsafe{libc::close(fd.file.as_raw_fd())}!=0{return Err(Error::Unknown)}fd.closed=true;}self.closed=true;Ok(())}
}
impl Drop for HeldQualification{fn drop(&mut self){if !self.closed{std::process::abort()}}}

#[cfg(test)]mod public_controls{
 use super::*;use std::os::unix::fs::PermissionsExt;use std::time::Instant;
 fn fixture()->(std::path::PathBuf,QualificationDATA){let p=Path::new("/Users/huangjiahao").join(format!("PUBLIC-postbuild-source-role-{}-{:?}",std::process::id(),Instant::now()));fs::create_dir(&p).unwrap();fs::set_permissions(&p,fs::Permissions::from_mode(0o700)).unwrap();let v=QualificationDATA{version:1,kind:"SOCIAL_SOURCE9_ORDINARY_RESOURCE_V1".into(),resource_id:"PUBLIC-physical-DATA".into(),bootstrap:"PUBLIC-NOT-APPROVED".into(),profile:1,statement_family:5,role:1,process_uid:unsafe{libc::geteuid()},process_gid:unsafe{libc::getegid()},scope_sha256:[2;32],credential_sha256:[3;32],source_epoch:7,resource_generation:8,native_image_path:"/PUBLIC-not-a-Native-image".into(),native_image_sha256:[1;32]};write(&p,&v);(p,v)}
 fn write(p:&Path,v:&QualificationDATA){let q=p.join("source-role-qualification.public.json");fs::write(&q,serde_json::to_vec(v).unwrap()).unwrap();fs::set_permissions(q,fs::Permissions::from_mode(0o600)).unwrap();}
 fn open(p:&Path,v:&QualificationDATA)->Acquisition{let s=fs::symlink_metadata(p).unwrap();let e=QualificationExpected{parent:p,identity:Identity{device:s.dev(),inode:s.ino(),uid:s.uid(),gid:s.gid(),mode:s.mode()&0o7777},resource_id:&v.resource_id,bootstrap:&v.bootstrap,statement_family:5,role:1,process_uid:v.process_uid,process_gid:v.process_gid,scope_sha256:[2;32],credential_sha256:[3;32],actual_image:Path::new("/PUBLIC-not-a-Native-image"),actual_image_sha256:[1;32]};HeldQualification::open_exact(&e,unsafe{libc::geteuid()})}
 #[test]fn postbuild_record_is_external_exact_fd_data_not_compiled_selfhash(){let(p,v)=fixture();let mut r=open(&p,&v);assert_eq!(r.error,None);let owner=r.owner.as_mut().unwrap();assert_eq!(owner.source_epoch_data(),Ok(7));owner.current().unwrap();owner.close().unwrap();owner.close().unwrap();}
 #[test]fn actual_record_substitution_denies_old_capture_new_read_is_independent(){let(p,mut v)=fixture();let mut first=open(&p,&v);let q=p.join("source-role-qualification.public.json");fs::rename(&q,p.join("retained-original.public.json")).unwrap();v.source_epoch=9;write(&p,&v);let owner=first.owner.as_mut().unwrap();assert_eq!(owner.current(),Err(Error::Changed));owner.close().unwrap();let mut next=open(&p,&v);assert_eq!(next.error,None);assert_eq!(next.owner.as_mut().unwrap().source_epoch_data(),Ok(9));next.owner.as_mut().unwrap().close().unwrap();}
 #[test]fn mismatched_image_profile_scope_role_and_source_epoch_fail_closed(){for mode in 0..5{let(p,mut v)=fixture();match mode{0=>v.native_image_sha256=[9;32],1=>v.profile=2,2=>v.scope_sha256=[9;32],3=>v.role=2,_=>v.source_epoch=0};write(&p,&v);let mut r=open(&p,&v);assert!(r.error.is_some());assert!(r.owner.is_some());r.owner.as_mut().unwrap().close().unwrap();}}
 #[test]fn symlink_leaf_and_duplicate_fields_never_become_registration(){for duplicate in [false,true]{let(p,v)=fixture();let q=p.join("source-role-qualification.public.json");if duplicate{let raw=fs::read_to_string(&q).unwrap().replacen("{","{\"version\":1,",1);fs::write(&q,raw).unwrap();}else{fs::rename(&q,p.join("retained.public")).unwrap();std::os::unix::fs::symlink(p.join("retained.public"),&q).unwrap();}let mut r=open(&p,&v);assert!(r.error.is_some());r.owner.as_mut().unwrap().close().unwrap();}}
 #[test]fn actual_child_close_error_stops_all_parent_fds_no_retry(){let(p,v)=fixture();let mut r=open(&p,&v);let mut owner=r.owner.take().unwrap();let child=owner.fds.last().unwrap().file.as_raw_fd();let parent=owner.fds[owner.fds.len()-2].file.as_raw_fd();assert_eq!(unsafe{libc::close(child)},0);assert_eq!(owner.close(),Err(Error::Unknown));assert_eq!(unsafe{libc::fcntl(parent,libc::F_GETFD)},libc::FD_CLOEXEC);assert_eq!(owner.fds.iter().filter(|f|f.close_selected).count(),1);assert_eq!(owner.close(),Err(Error::Unknown));assert_eq!(owner.fds.iter().filter(|f|f.close_selected).count(),1);std::mem::forget(owner);}
 #[cfg(target_os="linux")]
 #[test]fn linux_search_only_directory_never_requires_directory_read(){let(p,v)=fixture();fs::set_permissions(&p,fs::Permissions::from_mode(0o111)).unwrap();let mut r=open(&p,&v);assert_eq!(r.error,None);let o=r.owner.as_mut().unwrap();for fd in o.fds.iter().filter(|f|f.is_directory){let flags=unsafe{libc::fcntl(fd.file.as_raw_fd(),libc::F_GETFL)};assert!(flags&libc::O_PATH!=0);}o.current().unwrap();o.close().unwrap();fs::set_permissions(&p,fs::Permissions::from_mode(0o700)).unwrap();}
}

